package com.bank.repo.domain;

import java.math.BigDecimal;

// Pure domain object — no JPA annotations leaking across the boundary
public class Account {
    private final String id;
    private final String holderName;
    private final BigDecimal balance;

    public Account(String id, String holderName, BigDecimal balance) {
        this.id = id; this.holderName = holderName; this.balance = balance;
    }
    public String getId() { return id; }
    public BigDecimal getBalance() { return balance; }
    public boolean isOverdrawn() { return balance.signum() < 0; }
}
