package com.bank.repo.infra;

import com.bank.repo.domain.*;
import jakarta.persistence.*;
import org.springframework.stereotype.Repository;
import org.springframework.transaction.annotation.Transactional;
import java.util.*;
import java.util.stream.Collectors;

// JPA-backed implementation — maps entity <-> domain object
@Repository
public class JpaAccountRepository implements AccountRepository {
    @PersistenceContext private EntityManager em;

    @Override @Transactional(readOnly = true)
    public Optional<Account> findById(String id) {
        return Optional.ofNullable(em.find(AccountJpaEntity.class, id)).map(this::toDomain);
    }
    @Override @Transactional
    public Account save(Account a) {
        em.merge(new AccountJpaEntity(a.getId(), null, a.getBalance()));
        return a;
    }
    @Override @Transactional(readOnly = true)
    public List<Account> findOverdrawn() {
        return em.createQuery(
                "select a from AccountJpaEntity a where a.balance < 0", AccountJpaEntity.class)
            .getResultList().stream().map(this::toDomain).collect(Collectors.toList());
    }
    private Account toDomain(AccountJpaEntity e) {
        return new Account(e.getId(), e.getHolderName(), e.getBalance());
    }
}
