package com.bank.repo.infra;

import com.bank.repo.domain.*;
import java.util.*;
import java.util.stream.Collectors;

// Swappable in-memory implementation — ideal for tests, no database
public class InMemoryAccountRepository implements AccountRepository {
    private final Map<String, Account> store = new HashMap<>();

    @Override public Optional<Account> findById(String id) { return Optional.ofNullable(store.get(id)); }
    @Override public Account save(Account a) { store.put(a.getId(), a); return a; }
    @Override public List<Account> findOverdrawn() {
        return store.values().stream().filter(Account::isOverdrawn).collect(Collectors.toList());
    }
}
