package com.bank.repo.service;

import com.bank.repo.domain.*;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import java.util.List;

@Slf4j
@Service
@RequiredArgsConstructor
public class OverdraftService {
    private final AccountRepository repo;   // depends on INTERFACE, not JPA

    public List<Account> overdrawnAccounts() {
        List<Account> overdrawn = repo.findOverdrawn();
        log.warning(() -> "Found " + overdrawn.size() + " overdrawn accounts");
        return overdrawn;
    }
}
